# -*- coding: utf-8 -*-
"""Пробег 1.56: применить согласованные изменения в Pydroid 3."""
from pathlib import Path
import base64,zlib,json
DATA = ''

def main():
    report = Path(__file__).resolve().parent / 'итог.txt'
    try:
        changes, added = json.loads(zlib.decompress(base64.b64decode(DATA)))
        roots = [Path('/storage/emulated/0/Download'), Path(__file__).resolve().parent, Path.cwd()]
        found = []
        for root in roots:
            for name in ('Живой_блокнот.py','Пробег.py','main.py'):
                p = root / name
                if p.is_file() and p.resolve() not in found:
                    try:
                        text = p.read_text(encoding='utf-8-sig')
                        if 'class ProbegApp' in text and all(a in text for a,b in changes):
                            found.append(p.resolve())
                    except (OSError,UnicodeError): pass
        if len(found)!=1:
            raise RuntimeError('Не найден единственный подходящий исходник Пробега 1.55. Файлы не изменены.')
        p=found[0];text=p.read_text(encoding='utf-8-sig');compile(text,str(p),'exec')
        for a,b in changes:
            if text.count(a)!=1:raise RuntimeError('Участок кода отличается. Файл не изменён.')
            text=text.replace(a,b,1)
        anchor='    def _share_app_v1(self):'
        text=text.replace(anchor,added+'\n\n'+anchor,1)
        compile(text,str(p),'exec')
        p.with_name(p.name+'.bak').write_bytes(p.read_bytes())
        p.write_text(text,encoding='utf-8')
        message='Готово: интерфейс и инструкция обновлены. Создана одна .bak. Отправка APK для MAX работает в новом APK 1.56; Pydroid не содержит Android-компонента отправки.'
    except Exception as e:message='Изменения не выполнены: '+str(e)
    report.write_text(message,encoding='utf-8');print(message)
if __name__=='__main__':main()
